@bot.on_message() # پولینگ - polling
async def handler_polling(msg: Message):
    await msg.reply("پاسخ خودکار")
    if msg.text == "/off":
        bot.stop()

@bot.on_message_updates() # وبهوک - webhook
async def handler_webhook(msg: Message):
    await msg.reply("پاسخ خودکار")
    if msg.text == "/off":
        bot.stop()

# سایر دکوراتورها:
# @bot.on_edit() , @bot.on_delete() , @bot.on_all_message()
# @bot.on_edit_updates() , @bot.on_delete_updates() , @bot.on_all_message_updates()

msg = await bot.get_message("b...", "msg_id")
if msg:
    print(msg.text)

msgs = await bot.get_messages("b...", "msg_id", get_befor=5)
for m in msgs:
    print(m.text)

@bot.on_button_url("/my-button-webhook")
async def button_click(upd: UpdateButton):
    await upd.send_text("کلیک دریافت شد!")

@bot.on_ready()
async def ready():
    print("✅ ربات آماده است و تست ارتباط موفق بود!")

@bot.on_start()
async def started():
    print("🚀 کلاینت راه‌اندازی شد.")

@bot.on_run()
async def running():
    print("🔄 حلقهٔ اصلی دریافت پیام‌ها شروع شد.")

@bot.on_live()
async def live():
    print("🟢 ربات زنده است — همهٔ پیام‌های قبلی پردازش شدند.")

@bot.on_error(error_detail="full")
async def handle_error(error, update=None):
    print(f"❌ خطا رخ داد:\n{error}")

@bot.middleware()
async def log_middleware(update, next_handler):
    print(f"📩 پیام از {update.sender_id}")
    return await next_handler(update)

@bot.on_edit()
async def edited(msg: Message):
    print("ویرایش شد:", msg.text)

@bot.on_delete_updates()
async def deleted(msg: Message):
    print("حذف شد:", msg.message_id)

@bot.before_send()
async def check_spam(**kwargs):
    if "اسپم" in kwargs.get("text", ""):
        return False
    return True

@bot.after_send()
async def log_send(result, **kwargs):
    print("ارسال شد:", result)

@bot.before_run()
async def setup_db():
    print("اتصال به دیتابیس")

@bot.after_run()
async def cleanup():
    print("پاکسازی منابع")

@bot.on_log()
async def log_handler(log_entry):
    print(log_entry)
